"""MK1 product engine (mk5-native-audio.exe) from the source tree and the includes generated by the setup.

Same objects, flags and link order as the qualified product build (tools/mk1/runtime-inputs.json, formerly the
manual-temp-8 runtime build): C++17 -O2, -Werror, static, stripped, no PE timestamp; separate compilation through
tools/quality/cpp_build.py. The generated includes resolve through tools/setup/paths.generated_flags.
"""
from pathlib import Path
import json,os,shutil,sys
sys.path.insert(0,str(Path(__file__).resolve().parents[2]))
from tools.quality import run as q

ROOT=q.ROOT
INPUTS=ROOT/'tools/mk1/runtime-inputs.json'
FLAGS=['-std=c++17','-O2','-DUNICODE','-D_UNICODE','-Wall','-Wextra','-Werror','-Wno-unused-parameter',
       '-Wno-missing-field-initializers','-pthread','-municode','-I'+str(ROOT/'native/include'),'-I'+str(ROOT/'native/audio')]
LIBRARIES=['-static','-lbcrypt','-luser32','-lgdi32','-lwinmm','-ld3d12','-ldxgi','-ld3dcompiler','-ldxguid','-lwindowscodecs',
           '-lole32','-luuid','-s','-Wl,--no-insert-timestamp']


def sources():
    return [ROOT/p for p in json.loads(INPUTS.read_text('utf-8'))['objects']]


def roms_required():
    return json.loads(INPUTS.read_text('utf-8'))['roms_required']


def engine(out,*,timeout=3600):
    """Builds out/mk5-native-audio.exe; returns the compact cpp_build result."""
    from tools.quality import cpp_build
    out=Path(out);scratch=out/'build'
    if scratch.exists():shutil.rmtree(scratch)
    scratch.mkdir(parents=True)
    try:
        cc=q.DEFAULT_CC;env={'PATH':str(cc.parent)+os.pathsep+os.environ['PATH'],'TEMP':str(scratch),'TMP':str(scratch)}
        built=cpp_build.build(cc,FLAGS,sources(),LIBRARIES,scratch/'mk5-native-audio.exe',scratch,env=env,timeout=timeout,
                              compile_from_scratch=True)
        if built['passed']:os.replace(scratch/'mk5-native-audio.exe',out/'mk5-native-audio.exe')
        return q.compact(built)
    finally:shutil.rmtree(scratch,ignore_errors=True)


if __name__=='__main__':
    from tools.setup import paths,mk1
    mk1.inc_dir();out=paths.output('mk1');r=engine(out)
    print(json.dumps(dict(passed=r['passed'],sha256=q.sha(out/'mk5-native-audio.exe') if r['passed'] else None,
                          wall_seconds=r.get('wall_seconds'),tail=None if r['passed'] else r.get('output_tail')),indent=1))
    raise SystemExit(0 if r['passed'] else 1)
